```
import { createStore } from 'redux';

const initialState = {
  count: 0
};

function counterReducer(state = initialState, action) {
  switch (action.type) {
    case 'INCREMENT':
      return {
        ...state,
        count: state.count + 1
      };
    case 'DECREMENT':
      return {
        ...state,
        count: state.count - 1
      };
    default:
      return state;
  }
}

const store = createStore(counterReducer);

function handleIncrement() {
  store.dispatch({ type: 'INCREMENT' });
}

function handleDecrement() {
  store.dispatch({ type: 'DECREMENT' });
}

// 输出当前计数
console.log(store.getState()); // { count: 0 }

handleIncrement();
handleIncrement();
handleDecrement();

console.log(store.getState()); // { count: 1 }
```

在这个例子中，`counterReducer` 函数处理不同的 `ACTION` 类型（`INCREMENT` 和 `DECREMENT`），并返回新的状态对象。这个新的状态对象是通过将 `action` 对象应用到初始状态上获得的。每次事件处理后，新的状态被传递给 `store`，并可以在需要时获取更新后的状态。

